//! Actions-only original Router/TLS/Common physical reply, partial ciphertext,
//! parent retirement and lastDrop. No device, original SDK or business WRITE.
use super::*;
use n::{account_test_support::TempDatabase,group_event_delivery::IncomingGroupEvent,group_event_inbox,relation_journal::RelationConfiguration};
fn original(temp:&TempDatabase,root:&str)->(AttemptOwner,Arc<n::account_runs::RunToken>){
    let line="app-account-0123456789abcdef0123456789abcdef";let mut c=n::account_config::tests::native_fixture(root,"127.0.0.1",1);c.credentials.sdk.expires_at_unix_seconds=None;c.profile.incoming=None;c.profile.client_ex=true;c.profile.native_receivers=Some(config(true));c.profile.relation_events=Some(n::group_events::NativeRelationEventsConfig{group_updates:true});temp.database.with_conn(|c0|n::account_store::create(c0,line,&c,100)).unwrap();let run=Arc::new(temp.database.with_conn(|c|n::account_runs::register_runtime(c,line,1,&n::account_runtime::local_nonce().unwrap())).unwrap());let mut session=n::session::HostingSession::new(line.into());session.import(n::tests::imported(),100).unwrap();(session.begin_login(100).unwrap(),run)
}
fn packet()->Vec<u8>{
    let mut body=Writer::new();body.u32(1).unwrap();body.bytes(b"private-relation-label").unwrap();body.u32(1).unwrap();body.bytes(b"private-remark").unwrap();body.bytes(b"").unwrap();body.properties(&[]).unwrap();let body=body.finish();let mut args=Writer::versioned().unwrap();args.bytes(b"Group.Update").unwrap();args.properties(&[RpcProperty{key:b"Group.LastUpdateTime",value:b"0"},RpcProperty{key:b"Group.UpdateTime",value:b"1"}]).unwrap();args.bytes(body.expose_to_transport()).unwrap();let magic=91i32.to_be_bytes();let raw=n::rpc_envelope::encode_request(91,&[RpcProperty{key:b"id",value:b"MessageReceiver"},RpcProperty{key:b"__magic",value:&magic}],n::rpc_incoming::ONLINE_MESSAGE_METHOD.as_bytes(),args.finish().expose_to_transport()).unwrap();let mut p=vec![0];p.extend_from_slice(raw.expose_to_transport());p
}
async fn event_auth(handle:&RuntimeHandle,events:&mut mpsc::Receiver<RuntimeEvent>,who:&AttemptOwner,scope:&RpcConnectionScope){
    let setup=NativeReceiverSetup::capture(NativeReceiverPolicy::capture(&config(true)).unwrap(),true,None).unwrap();let cmd=handle.command_handle();cmd.arm_native_receivers(who,scope,setup).await.unwrap();cmd.arm_relation_events(who,scope,n::group_events::NativeRelationEventsConfig{group_updates:true}).await.unwrap();authenticated(handle,events,who,scope).await;cmd.configure_native_receivers(who,scope,7).await.unwrap();
}
async fn next(events:&mut mpsc::Receiver<RuntimeEvent>,who:&AttemptOwner,scope:&RpcConnectionScope)->Box<IncomingGroupEvent>{
    let e=bounded(events.recv()).await.unwrap();let mut values=e.into_events(who,scope).unwrap();assert_eq!(values.len(),1);let OfflineEvent::GroupEvent(e)=values.pop().unwrap()else{panic!("original group event")};e
}
fn proof(temp:&TempDatabase,run:Arc<n::account_runs::RunToken>,e:&IncomingGroupEvent,gate:Arc<ImReceiptGate>)->group_event_inbox::CommittedGroupEvent{
    let cfg=Arc::new(temp.database.with_conn(|c|RelationConfiguration::capture(c,run.line_id(),run.revision(),Some(&e.scope()))).unwrap());group_event_inbox::commit(&temp.database,run,e,gate,&cfg).unwrap()
}
fn rows(db:&crate::platform::db::Database)->i64{db.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_relation_events",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap()}
#[tokio::test]async fn group_event_io_original_commit_precedes_physical_positive_and_proof_remains_held_after_logout_join(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let route=router_policy(&cert.root,listener.local_addr().unwrap().port());let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let(who,run)=original(&temp,&cert.root);let db=temp.database.clone();let(go,wait)=oneshot::channel();
    let peer=async move{let mut p=CommonPeer::open(listener,server).await;peer_login(&mut p).await;wait.await.unwrap();p.send(&[packet()]).await;let data=p.next().await.unwrap();assert_eq!(data[0],1);let r=n::rpc_envelope::decode_reply(&data[1..]).unwrap();assert_eq!(r.call_id,91);assert_eq!(r.result_stream,[0,1,0,0,0,0]);assert_eq!(rows(&db),1);peer_logout(&mut p).await;};
    let client=async{let conn=connected(&route,who.clone(),Instant::now()+Duration::from_secs(6)).await;let scope=conn.connection_scope();let(mut handle,mut events)=conn.attach().unwrap();event_auth(&handle,&mut events,&who,&scope).await;go.send(()).unwrap();let e=next(&mut events,&who,&scope).await;assert_eq!(rows(&temp.database),0);let p=proof(&temp,run,&e,ImReceiptGate::fresh());let receipt=bounded(handle.command_handle().complete_group_event(&who,&scope,e.ticket(),Some(&p))).await.unwrap();assert!(receipt.matches(&who,&scope));assert!(events.try_recv().is_err());assert!(bounded(handle.logout(&who,&scope,&[])).await.unwrap().io_released());assert!(scope.native_rpc_resources().0>0);drop(e);assert!(scope.native_rpc_resources().0>0);drop(p);assert_eq!(scope.native_rpc_resources(),(0,0));};tokio::join!(Box::pin(bounded(peer)),Box::pin(bounded(client)));
}).await;}
#[derive(Clone,Copy)]enum End{Parent,WaitDrop,Deadline}
async fn partial(end:End){
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let route=router_policy(&cert.root,listener.local_addr().unwrap().port());let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let(who,run)=original(&temp,&cert.root);let(go,wait)=oneshot::channel();
    let peer=async move{let mut p=CommonPeer::open(listener,server).await;peer_login(&mut p).await;wait.await.unwrap();p.send(&[packet()]).await;while let Some(bytes)=p.next_input_only().await{assert!(matches!(bytes.as_slice(),[2]|[14]),"no complete group ACK, SDK relogin or retried event escapes partial frame");}};
    let client=async{let mut conn=connected(&route,who.clone(),Instant::now()+Duration::from_secs(6)).await;let prefix=n::router_runtime::tests::auxiliary_io::AuxiliaryIoTest::original_unarmed(1);n::common_runtime::tests::gate_auxiliary_prefix(conn.common.as_mut().unwrap(),prefix.clone());let scope=conn.connection_scope();let(mut handle,mut events)=conn.attach().unwrap();event_auth(&handle,&mut events,&who,&scope).await;go.send(()).unwrap();let e=next(&mut events,&who,&scope).await;let gate=ImReceiptGate::fresh();let p=proof(&temp,run,&e,gate.clone());prefix.arm();let commands=handle.command_handle();let mut completing=Box::pin(commands.complete_group_event(&who,&scope,e.ticket(),Some(&p)));let started=Instant::now();
        tokio::select!{r=completing.as_mut()=>panic!("partial reply cannot complete {r:?}"),_=bounded(prefix.paused())=>{}}assert_eq!(prefix.accepted.load(Ordering::SeqCst),1);assert!(!prefix.dropped.load(Ordering::SeqCst));
        let reason=match end{End::Parent=>{gate.retire();assert_eq!(bounded(completing).await.err(),Some(RuntimeError::Cancelled));RuntimeError::Cancelled},End::WaitDrop=>{drop(completing);RuntimeError::Cancelled},End::Deadline=>{assert_eq!(bounded(completing).await.err(),Some(RuntimeError::Timeout));assert!(started.elapsed()>=Duration::from_secs(2));assert!(started.elapsed()<Duration::from_secs(3),"original shorter two-second IO budget is not renewed to the three-second event/actor budget");RuntimeError::Timeout}};
        bounded(scope.closed()).await;let joined=bounded(handle.close()).await;assert!(joined.io_released());assert_eq!(joined.reason,reason);assert!(prefix.dropped.load(Ordering::SeqCst),"same main fd Drop before Join");assert_eq!(prefix.accepted.load(Ordering::SeqCst),1);assert_eq!(rows(&temp.database),1,"observation remains DATA, not refunded because ACK was partial");assert!(scope.native_rpc_resources().0>0);drop(e);drop(p);assert_eq!(scope.native_rpc_resources(),(0,0));
    };tokio::join!(Box::pin(bounded(peer)),Box::pin(bounded(client)));
}
#[tokio::test]async fn group_event_io_parent_retirement_after_one_ciphertext_byte_stops_original_reply_and_joins(){Box::pin(partial(End::Parent)).await;}
#[tokio::test]async fn group_event_io_waiter_drop_after_one_ciphertext_byte_does_not_resend_or_forget_observation(){Box::pin(partial(End::WaitDrop)).await;}
#[tokio::test]async fn group_event_io_partial_reply_original_deadline_closes_same_fd_without_budget_refund(){Box::pin(partial(End::Deadline)).await;}
